SELECT 
  100.0 * SUM(CASE WHEN location_type = 'public_dc' THEN energy_kwh ELSE 0 END) / SUM(energy_kwh) AS pct_energy_public_dc
FROM gishub.fleet.charging_sessions;

SELECT 
  100.0 * SUM(CAST(CASE WHEN location_type = 'public_dc' THEN energy_kwh ELSE 0 END AS DOUBLE)) / SUM(CAST(energy_kwh AS DOUBLE)) AS pct_energy_public_dc
FROM gishub.fleet.charging_sessions;

SELECT 
  100.0 * SUM(CASE WHEN cs.location_type = 'public_dc' THEN cs.energy_kwh ELSE 0 END) / SUM(cs.energy_kwh) AS pct_energy_public_dc
FROM gishub.fleet.charging_sessions cs;
